static inline double s_mir_i64_to_f64(int64_t value) {
	uint64_t magnitude = value < 0 ? (uint64_t)(-(value + 1)) + UINT64_C(1) : (uint64_t)value;
	if (magnitude <= UINT64_C(9007199254740992)) return (double)value;
	uint64_t mantissa = magnitude; unsigned shift = 0;
	while (mantissa > UINT64_C(9007199254740991)) { mantissa >>= 1; ++shift; }
	uint64_t remainder = magnitude & ((UINT64_C(1) << shift) - 1);
	uint64_t halfway = UINT64_C(1) << (shift - 1);
	if (remainder > halfway || (remainder == halfway && (mantissa & 1))) ++mantissa;
	double rounded = ldexp((double)mantissa, (int)shift);
	return value < 0 ? -rounded : rounded;
}
